import React, { useState } from "react";
import { ref, get, set } from "firebase/database";
import { db, auth } from "../firebase/config"; // ✅ Import dari dalam src/
import { useAuthState } from "react-firebase-hooks/auth";
import { encodeEmail } from "../utils/encodeEmail"; // ✅ Gunakan helper
import "../styles/contactlist.css";

const AddContact = ({ onContactAdded }) => {
  const [email, setEmail] = useState("");
  const [user] = useAuthState(auth);
  const [loading, setLoading] = useState(false);

  const handleAdd = async () => {
    if (!email) return;

    setLoading(true);

    const emailKey = encodeEmail(email);
    const currentUserKey = encodeEmail(user.email);

    const contactRef = ref(db, `users/${emailKey}`);
    const snapshot = await get(contactRef);

    if (snapshot.exists()) {
      await set(ref(db, `users/${currentUserKey}/contacts/${emailKey}`), true);
      onContactAdded();
      alert("Kontak berhasil ditambahkan");
    } else {
      alert("Email tidak ditemukan");
    }

    setEmail("");
    setLoading(false);
  };

  return (
    <div className="card mb-3 shadow-sm">
      <div className="card-body">
        <h5 className="card-title">Tambah Kontak</h5>
        <div className="input-group">
          <input
            type="email"
            className="form-control"
            placeholder="Masukkan email teman"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            disabled={loading}
          />
          <button
            className="btn btn-primary"
            onClick={handleAdd}
            disabled={loading}
          >
            {loading ? "Menambahkan..." : "Tambah"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AddContact;
