import React, { useState, useEffect } from "react";
import { useAuthState } from "react-firebase-hooks/auth";
import { auth } from "../firebase/config";
import AddContact from "../components/AddContact";
import ContactList from "../components/ContactList";
import ChatBox from "../components/ChatBox";
import "./ChatResponsive.css";

const ChatPage = () => {
  const [user, loading] = useAuthState(auth);
  const [selectedContact, setSelectedContact] = useState(null);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const handleBack = () => setSelectedContact(null);

  if (loading) return <div>Loading...</div>;
  if (!user) return <div>Silakan login terlebih dahulu.</div>;

  return (
    <div className="chat-wrapper">
      {/* Sidebar tampil di desktop ATAU saat belum pilih kontak di mobile */}
      {(!isMobile || !selectedContact) && (
        <aside className="chat-sidebar">
          <AddContact onContactAdded={() => {}} />
          <ContactList onSelectContact={setSelectedContact} />
        </aside>
      )}

      {/* Chat tampil jika kontak dipilih */}
      {(!isMobile || selectedContact) && (
        <main className="chat-main">
          {selectedContact ? (
            <ChatBox
              selectedContact={selectedContact}
              currentUser={user}
              onBackClick={handleBack} // tetap disediakan kalau nanti kamu mau aktifkan lagi
            />
          ) : (
            !isMobile && (
              <div className="chat-placeholder">
                Pilih kontak untuk mulai chat
              </div>
            )
          )}
        </main>
      )}
    </div>
  );
};

export default ChatPage;
