import React, { useEffect, useState } from "react";
import { ref, onValue } from "firebase/database";
import { db } from "../firebase/config";
import { useAuthState } from "react-firebase-hooks/auth";
import { auth } from "../firebase/config";
import "../styles/contactlist.css";
import { encodeEmail } from "../utils/encodeEmail";

const ContactList = ({ onSelectContact }) => {
  const [contacts, setContacts] = useState([]);
  const [user] = useAuthState(auth);

  useEffect(() => {
    if (!user) return;

    const userKey = encodeEmail(user.email);
    const contactRef = ref(db, `users/${userKey}/contacts`);

    const unsubscribe = onValue(contactRef, async (snapshot) => {
      const contactList = [];

      if (snapshot.exists()) {
        const contactKeys = Object.keys(snapshot.val());

        for (const key of contactKeys) {
          const contactSnap = await new Promise((resolve) =>
            onValue(ref(db, `users/${key}`), resolve, { onlyOnce: true })
          );
          if (contactSnap.exists()) {
            contactList.push(contactSnap.val());
          }
        }
      }

      setContacts(contactList);
    });

    return () => unsubscribe();
  }, [user]);

  return (
    <div className="card shadow-sm">
      <div className="card-body">
        <h5 className="card-title">Daftar Kontak</h5>
        <ul className="list-group contact-list">
          {contacts.length === 0 && (
            <li className="list-group-item text-muted">Belum ada kontak</li>
          )}
          {contacts.map((contact, index) => (
            <li
              key={index}
              className="list-group-item d-flex align-items-center contact-item"
              onClick={() => onSelectContact(contact)}
              style={{ cursor: "pointer" }}
            >
              <div className="profile-pic me-3">
                <img
                  src="https://www.freeiconspng.com/uploads/am-a-19-year-old-multimedia-artist-student-from-manila--21.png"
                  alt="avatar"
                  className="rounded-circle"
                  width={40}
                  height={40}
                />
              </div>
              <div className="flex-grow-1">
                <strong>{contact.name || contact.email?.split("@")[0]}</strong>
                <div className="text-muted small">{contact.email}</div>
              </div>
              <span className="badge bg-primary rounded-pill">Chat</span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default ContactList;
