import React, { useEffect, useRef, useState } from "react";
import "../styles/chatbox.css";
import {
  ref,
  push,
  onValue,
  serverTimestamp,
  query,
  orderByChild,
  set,
  remove,
} from "firebase/database";
import { db } from "../firebase/config";

const ChatBox = ({ selectedContact, currentUser, onBackClick }) => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef(null);

  const formatKey = (email) =>
    (email || "").toString().replace(/\./g, "_dot_").replace(/@/g, "_at_");

  const contactEmail =
    typeof selectedContact === "string"
      ? selectedContact
      : selectedContact?.email || "";

  const currentUserKey = formatKey(currentUser.email);
  const contactKey = formatKey(contactEmail);
  const chatId =
    currentUserKey < contactKey
      ? `${currentUserKey}_${contactKey}`
      : `${contactKey}_${currentUserKey}`;

  // Ambil pesan
  useEffect(() => {
    const chatRef = query(ref(db, `chats/${chatId}`), orderByChild("timestamp"));
    const unsubscribe = onValue(chatRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const messagesArray = Object.values(data);
        setMessages(messagesArray);
      } else {
        setMessages([]);
      }
    });

    return () => unsubscribe();
  }, [chatId]);

  // Ambil status mengetik
  useEffect(() => {
    const typingRef = ref(db, `typing/${chatId}/${contactKey}`);
    const unsubscribe = onValue(typingRef, (snapshot) => {
      setIsTyping(snapshot.val() === true);
    });

    return () => unsubscribe();
  }, [chatId, contactKey]);

  // Kirim pesan & tambahkan ke kontak penerima
  const handleSend = async () => {
    if (input.trim() === "") return;

    const chatRef = ref(db, `chats/${chatId}`);
    await push(chatRef, {
      sender: currentUser.email,
      text: input,
      timestamp: serverTimestamp(),
    });

    // Tambahkan currentUser ke kontak penerima
    await set(ref(db, `users/${contactKey}/contacts/${currentUserKey}`), true);

    // Tambahkan contact ke kontak currentUser (agar satu arah pun tetap sinkron)
  await set(ref(db, `users/${currentUserKey}/contacts/${contactKey}`), true);


    setInput("");
    remove(ref(db, `typing/${chatId}/${currentUserKey}`));
  };

  const handleTyping = (e) => {
    setInput(e.target.value);
    const typingRef = ref(db, `typing/${chatId}/${currentUserKey}`);
    if (e.target.value.trim() !== "") {
      set(typingRef, true);
    } else {
      remove(typingRef);
    }
  };

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  return (
    <div className="chat-box d-flex flex-column" style={{ height: "100%" }}>
      {/* Header */}
      <div className="chat-header px-4 py-3 border-bottom bg-white shadow-sm">
        <div className="d-flex align-items-center gap-3">
          <button
            className="btn btn-link p-0 me-2"
            style={{
              textDecoration: "none",
              fontWeight: "bold",
              fontSize: "1.2rem",
              color: "#007bff",
            }}
            onClick={onBackClick}
          >
            ←
          </button>

          {/* Foto profil & nama */}
        

          <div className="d-flex flex-column">
            <strong className="fs-5" style={{ color: "#222" }}>
              {selectedContact?.displayName || selectedContact?.email || "Teman"}
            </strong>
            {isTyping && (
              <small className="text-muted" style={{ fontStyle: "italic" }}>
                sedang mengetik...
              </small>
            )}
          </div>
        </div>
      </div>

      {/* Chat Messages */}
      <div className="chat-messages flex-grow-1 p-3 overflow-auto">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`message mb-2 ${
              msg.sender === currentUser.email ? "text-end" : "text-start"
            }`}
          >
            <div className="chat-bubble">{msg.text}</div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Pesan */}
      <div className="chat-input d-flex p-3 border-top bg-white">
        <input
          type="text"
          className="form-control me-2"
          placeholder="Ketik pesan..."
          value={input}
          onChange={handleTyping}
          onKeyDown={(e) => e.key === "Enter" && handleSend()}
        />
        <button className="btn btn-primary" onClick={handleSend}>
          Kirim
        </button>
      </div>
    </div>
  );
};

export default ChatBox;
